echo "written" && wc -l /app/polyglot/main.rs

cd /app/polyglot && diff /tmp/rust.out /tmp/cpp.out && echo "RUST==CPP for N=0..100" && perl -Mbignum -e '
open(my $f, "<", "/tmp/rust.out") or die;
my @ref = map { $_+0 } <$f>; close $f;
my ($a,$b)=(1,1);
my %ref; $ref{0}=$a;
for my $n (1..100) { my $t=$a+$b; $a=$b; $b=$t; $ref{$n}=($a % (2**64)); }
my $bad=0;
for my $n (0..100) { my $got=$ref{$n}+0; if ($ref{$n} != ($ref{$n}+0)) { } if ("" . $ref{$n} ne (map {$_+0} <$f>)[0]) {} }
for my $n (0..100) {
  open(my $g, "<", "/tmp/rust.out");
  my @g = <$g>; close $g;
  my $got = $g[$n]; chomp $got;
  my $e = "$ref{$n}";
  if ($got ne $e) { $bad++; print "MISMATCH n=$n got=$got exp=$e\n"; }
}
print $bad==0 ? "PERL-BIGNUM REFERENCE MATCHES for N=0..100\n" : "FAILED\n";
print "n=92 -> $ref{92}\nn=93 -> $ref{93}\nn=100 -> $ref{100}\n";
'

cd /app/polyglot && perl -e '
my $M = 2**32;
sub add64 {
  my ($h1,$l1,$h2,$l2) = @_;
  my $l = $l1 + $l2;
  my $h = $h1 + $h2 + int($l / $M);
  return ($h % $M, $l % $M);
}
sub fmt { my ($h,$l) = @_; my $s = sprintf("%u%010u", $h, $l); $s =~ s/^0+//; return length($s) ? $s : "0"; }
my @val;
my ($ah,$al) = (0,1); my ($bh,$bl) = (0,1);
$val[0] = fmt($ah,$al); $val[1] = fmt($bh,$bl);
for my $n (2..100) {
  my ($ch,$cl) = add64($ah,$al,$bh,$bl);
  ($ah,$al) = ($bh,$bl); ($bh,$bl) = ($ch,$cl);
  $val[$n] = fmt($bh,$bl);
}
open(my $g, "<", "/tmp/rust.out") or die; my @got = <$g>; close $g;
my $bad = 0;
for my $n (0..100) {
  my $g = $got[$n]; chomp $g;
  if ($g ne $val[$n]) { $bad++; print "MISMATCH n=$n got=$g exp=$val[$n]\n"; }
}
print $bad == 0 ? "INDEPENDENT BIGNUM REFERENCE MATCHES rust+cpp for N=0..100\n" : "FAILED\n";
print "f(0..12) = ", join(",", @val[0..12]), "\n";
print "f(92)  = $val[92]\nf(93)  = $val[93]\nf(100) = $val[100]\n";
'

cat > /tmp/ref.pl <<'PERLEOF'
sub dadd {
  my ($x, $y) = @_;
  my @a = reverse split //, $x;
  my @b = reverse split //, $y;
  my ($c, $out) = (0, '');
  for my $i (0 .. ($#a > $#b ? $#a : $#b)) {
    my $s = ($a[$i] // 0) + ($b[$i] // 0) + $c;
    $out = int($s % 10) . $out;
    $c = int($s / 10);
  }
  $out = $c . $out if $c;
  $out =~ s/^0+(?=\d)//;
  return $out;
}
sub dsub { # x >= y
  my ($x, $y) = @_;
  my @a = reverse split //, $x;
  my @b = reverse split //, $y;
  my ($c, $out) = (0, '');
  for my $i (0 .. $#a) {
    my $s = ($a[$i] // 0) - ($b[$i] // 0) - $c;
    if ($s < 0) { $s += 10; $c = 1 } else { $c = 0 }
    $out = $s . $out;
  }
  $out =~ s/^0+(?=\d)//;
  return $out;
}
sub dcmp {
  my ($x, $y) = @_;
  return length($x) <=> length($y) if length($x) != length($y);
  return $x cmp $y;
}
my $M = "18446744073709551616";
my ($a, $b) = ("1", "1");
my @val = ("1", "1");
for my $n (2 .. 100) {
  my $c = dadd($a, $b);
  $c = dsub($c, $M) if dcmp($c, $M) >= 0;
  ($a, $b) = ($b, $c);
  $val[$n] = $c;
}
open(my $g, "<", "/tmp/rust.out") or die;
my @got = <$g>; close $g;
my $bad = 0;
for my $n (0 .. 100) {
  my $g = $got[$n]; chomp $g; $g =~ s/^0+(?=\d)//;
  if ($g ne $val[$n]) { $bad++; print "MISMATCH n=$n got=$g exp=$val[$n]\n"; }
}
print $bad == 0 ? "DECIMAL-STRING REFERENCE MATCHES rust AND cpp for N=0..100\n" : "FAILED: $bad\n";
print "f(0..12)   = ", join(",", @val[0..12]), "\n";
print "f(90)      = $val[90]\n";
print "f(92)      = $val[92]\n";
print "f(93)      = $val[93]\n";
print "f(100)     = $val[100]\n";
PERLEOF
perl /tmp/ref.pl
